        @else<div class="support-flow-panel"><button wire:click="backToAccount" class="support-back">← تغییر سرویس</button><h3>توضیحات درخواست</h3><p class="support-muted">مشکل خود را کامل توضیح دهید تا سریع‌تر بررسی شود.</p><input wire:model="subject" placeholder="موضوع درخواست" class="support-input"><textarea wire:model="message" rows="6" placeholder="توضیحات کامل مشکل..." class="support-input"></textarea><div class="support-form-row"><select wire:model="priority" class="support-input"><option value="normal">اولویت عادی</option><option value="high">اولویت بالا</option></select><input wire:model="attachment" type="file" class="support-input"></div><button wire:click="submitTicket" wire:loading.attr="disabled" wire:target="submitTicket" class="support-primary"><span wire:loading.remove wire:target="submitTicket">ثبت درخواست پشتیبانی</span><span wire:loading wire:target="submitTicket">در حال ثبت...</span></button></div>@endif
