    @if($selected)<section class="support-card"><div class="support-card-head"><div><span class="support-label">پیگیری درخواست</span><h2>#{{ $selected->number }}</h2></div><span class="support-status">{{ $selected->status_label }}</span></div><h3 class="support-ticket-subject">{{ $selected->subject }}</h3><div class="support-messages">@foreach($selected->messages as $msg)<div class="support-message {{ $msg->user_id===auth()->id()?'mine':'' }}"><small>{{ $msg->user->name ?? 'پشتیبانی' }}</small><p>{{ $msg->message }}</p></div>@endforeach</div>@if($selected->status!=='closed')<textarea wire:model="message" rows="3" placeholder="پاسخ خود را بنویسید..." class="support-input"></textarea><button wire:click="reply" class="support-primary mt-3">ارسال پاسخ</button>@endif</section>@endif

